void settled(Document&d){if(!d.wait_asset(std::chrono::seconds(120))||!d.wait_mesh(std::chrono::seconds(120))||!d.frame().state->error.empty())throw std::runtime_error("Derived key consumer: "+d.frame().state->error);}
Scene typed_source(bool native_attributes){
 // A genuine authored CC0 source variant with nonzero raw colours, so source
 // shading remains sensitive without exporter-internal material rewrites.
 auto scene=colored_vrm_fixture::model(true,true,true,false,false);auto&o=scene.active();auto binding=std::make_shared<SourceMaterialBindings>(*o.material_bindings);binding->material.parameters.toony=0;binding->material.parameters.shift=.05f;
 if(native_attributes){o.shape_source=capture_polygon_origin(scene,o.id);auto frames=std::make_shared<NormalFrameSet>(*binding->normal_frames);auto role=std::make_shared<NormalFrames>(*frames->pbr);role->source_vertices.clear();role->source_corners.clear();role->source_vertex_count=role->source_corner_count=0;frames->pbr=frames->mtoon=role;binding->normal_frames=frames;}
 o.material_bindings=binding;scene.validate();SourceUvBakeInput uv;uv.paint=o.painted;uv.appearance=o.appearance;uv.current_material=o.material_bindings;uv.current_deformation=o.deformation;uv.source_vertices=o.painted->mesh().indices;const auto old=o.painted->mesh();for(auto v:uv.source_vertices){uv.target.positions.push_back(old.positions[v]);uv.target.normals.push_back(old.normals[v]);uv.target.uv.push_back(old.uv[v]);uv.target.indices.push_back(uint32_t(uv.target.indices.size()));}auto adopted=adopt_source_uv_bake(bake_source_uv(uv));o.painted=adopted.paint;o.material_bindings=adopted.material_bindings;o.deformation=adopted.deformation;o.appearance=adopted.appearance;scene.validate();
 check(o.painted->mesh().positions.size()==6&&o.material_bindings->uv_origin->paint->mesh().positions.size()==4,"Real typed SourceUV split preserves current6 and original-native4 ownership");
 const auto id=o.id;ShapeKeyEdit edit;edit.action=ShapeKeyAction::Replace;edit.target=0;edit.positions=o.painted->mesh().positions;edit.positions[0].z+=.09f;edit.positions[3].z-=.08f;author_shapekey(scene,id,edit);edit.action=ShapeKeyAction::Duplicate;edit.name="Pixel duplicate";author_shapekey(scene,id,edit);edit.action=ShapeKeyAction::Replace;edit.target=1;edit.positions=scene.active().painted->mesh().positions;for(size_t v=0;v<edit.positions.size();++v)edit.positions[v]+=scene.active().deformation->morphs->targets[1].delta[v];edit.positions[2].x+=.07f;edit.positions[5].y-=.04f;author_shapekey(scene,id,edit);
 auto d=std::make_shared<DeformationState>(*scene.active().deformation);d->morph_weights={.35f,.65f};scene.active().deformation=d;edit.action=ShapeKeyAction::CaptureMix;edit.name="Pixel captured mix";author_shapekey(scene,id,edit);scene.validate();return scene;
}
void pose(Scene&s,int mode,float w){auto d=*s.active().deformation;d.morph_weights.assign(d.morphs->targets.size(),0);d.morph_weights[0]=.2f;d.morph_weights.back()=w;d.pose.clear();for(const auto &bone:d.skeleton->bones)d.pose.push_back(bone.rest);if(mode){d.pose[0].scale=mode==1?Vec3{1.1f,.85f,.65f}:Vec3{.85f,1.05f,1.4f};const float a=mode==1?.2f:-.25f;d.pose[1].rotation={std::cos(a/2),0,std::sin(a/2),0};d.pose[1].scale=mode==1?Vec3{.9f,1.1f,1.4f}:Vec3{1.15f,.9f,.8f};}s.set_deformation(s.active().id,std::move(d));}
void rendered(Scene source,bool typed,const std::filesystem::path&dir,SurfaceRenderer&renderer,Fbo&fbo,prepared_normal_consumer::Renderer&external){
 std::filesystem::create_directories(dir);source.save(dir/"before.dsculpt");source=Scene::load(dir/"before.dsculpt");const auto exact=source.encode();Pixels zero;
 for(int p=0;p<3;++p)for(float w:{0.f,.35f,1.f}){
  auto scene=source;pose(scene,p,w);Document d;d.replace(scene);settled(d);const auto project=d.copy_scene().encode();d.shading(false);settled(d);const auto pbr=draw(renderer,d.frame().surface);const auto uploads=renderer.buffer_stats();const auto images=renderer.texture_stats();check(pbr==draw(renderer,d.frame().surface)&&renderer.buffer_stats().geometry_uploads==uploads.geometry_uploads&&renderer.texture_stats().uploads==images.uploads,"Derived6 second eye/noop reuses immutable geometry and images");
  auto path=dir/("p"+std::to_string(p)+"-w"+std::to_string(int(w*100))+".glb");d.export_asset(path,AssetExportFormat::Glb).get();prepared_normal_consumer::Model model(path);fbo.bind();external.render(model.data);auto pixels=read();const auto error=delta(pbr,pixels);size_t covered=0;for(size_t i=3;i<pixels.size();i+=4)covered+=pixels[i]>0;std::cout<<"DERIVED_PBR pose="<<p<<" weight="<<w<<" max="<<error<<" covered="<<covered<<std::endl;check(covered>300&&error<=4,"Real CorePBR command matches independent current derived6 GLB across mixed skin/morphs");
  if(!p&&w==0)zero=pbr;if(!p&&w==1){check(delta(zero,pbr)>2,"Independent seam key makes a real visible current geometry/direction change");auto &primitive=model.data->meshes[0].primitives[0];const auto slot=scene.active().deformation->morphs->targets.size()-1;auto &target=primitive.targets[slot];const auto old=target.attributes;const auto old_count=target.attributes_count;std::vector<cgltf_attribute> kept;for(size_t a=0;a<old_count;++a)if(old[a].type==cgltf_attribute_type_position)kept.push_back(old[a]);struct RestoreAttributes{cgltf_morph_target &target;cgltf_attribute *attributes;cgltf_size count;~RestoreAttributes(){target.attributes=attributes;target.attributes_count=count;}} restore{target,old,old_count};target.attributes=kept.data();target.attributes_count=kept.size();fbo.bind();external.render(model.data);check(delta(pixels,read())>2,"Independent pixels visibly require the new artist N/T channels, not only POSITION");target.attributes=old;target.attributes_count=old_count;}
  if(typed){d.authored_shading();settled(d);const auto authored=draw(renderer,d.frame().surface);auto vrm=dir/("p"+std::to_string(p)+"-w"+std::to_string(int(w*100))+".vrm");d.export_asset(vrm,AssetExportFormat::Avatar).get();prepared_normal_consumer::Model avatar(vrm);fbo.bind();external.render(avatar.data,&avatar.json.at("extensions").at("VRM"));const auto vrm_error=delta(authored,read());std::cout<<"DERIVED_VRM pose="<<p<<" weight="<<w<<" max="<<vrm_error<<std::endl;check(vrm_error<=4,"Independent raw-MToon VRM preserves genuine derived6 POSITION/N/T under current mixed pose");}
  check(d.copy_scene().encode()==project,"Actual authored/CorePBR commands and exports never rewrite stored roles, data or source history");
 }
 auto late_cancel=[&](bool avatar){const auto path=dir/(avatar?"cancel.vrm":"cancel.glb");const std::string marker="existing-output-before-derived-key-export";{std::ofstream file(path,std::ios::binary);file<<marker;}size_t calls=0;bool rejected=false;try{auto before=[&]{++calls;throw std::runtime_error("cancel-derived-domain-export");};if(avatar){VrmExportOptions options;options.before_commit=before;export_vrm(source.surfaces(),path,options);}else{GltfExportOptions options;options.before_commit=before;export_glb(source.surfaces(),path,options);}}catch(const std::exception&e){rejected=std::string_view(e.what())=="cancel-derived-domain-export";}std::ifstream file(path,std::ios::binary);std::string data((std::istreambuf_iterator<char>(file)),{});check(rejected&&calls==1&&data==marker&&source.encode()==exact,"Actual derived-domain format compilation preserves before_commit cancellation and existing file/source exactly");};late_cancel(false);if(typed)late_cancel(true);
 check(source.encode()==exact,"All independent derived-domain consumers preserve the exact saved source");
}
